/* ==============================================================
   Objeto ..........: dbo.IV$RESULTADOFULL
   Tipo ............: VIEW
   Criado em .......: 2025-02-17 17:35:38
   Modificado em ...: 2025-02-17 17:35:38
   Linhas ..........: 1
   Escreve em tabela: nao
   Tabelas referidas: IV_ACAO, IV_CODPROCESSO, IV_PROCRESULTADO, IV_RESULTADO
   Fonte: banco CRM (Vortice CRM / Tracbel) - extracao somente leitura
   ============================================================== */

     CREATE VIEW IV$RESULTADOFULL   (   RESULTADO       ,ACAO       ,DESCRICAO       ,DESCREDUZIDA       ,ORDEM       ,DESCRICAOFULL       ,DESCREDFULL       ,ACAODESCRICAO       ,DESCREDUZIDAACAO       ,EMUSO       ,CODPROCESSO       ,TIPOPROCESSO       ,ADVERTENCIA       ,ASSUNTOCMPL       ,ASSUNTOEMAIL       ,CANALPADRAO       ,CMPLTTXTPADRAO       ,DESCQTDE       ,DESCVALOR       ,PCTE       ,QTDEMAXPORACAO       ,CTRLINTERATIVO       ,CTRLCONCLUSAO       ,CTRLDETALHE       ,CTRLFORMACONTATO       ,CTRLREAGENDA       ,CTRLCONFIRMAREAG       ,CTRLREAGENDASILO       ,CTRLMUDARATDREAG       ,CTRLFORMULARIO       ,CTRLDURACAO       ,CTRLVALOR       ,CTRLPRODUTIVO       ,CTRLPRODUTO       ,CTRLVENDEDOR       ,CTRLMOTIVO       ,CTRLDEPARTAMENTO       ,CTRLCAMPANHA       ,CTRLCONTATOPF       ,CTRLCONTATOPJ       ,CTRLCLIENTEATIVO       ,CTRLDETALHEPROC       ,CTRLDESCRSTATUSPROC       ,CTRLSTATUSPROC       ,CTRLPERSPECTIVAPROC       ,CTRLVALORPROC       ,CTRLDTAENCERRAPROC       ,CTRLPROJETO       ,CTRLIMAGEM       ,CTRLCTIDISPONIVEL       ,CTRLRESUMOPROC       ,INDCOMPLEMENTO       ,INDPERMCONCLUIR       ,INDCONCLUI       ,INDINCLMANUAL       ,INDPERMREAGENDAR       ,INDPERMEMAIL       ,RQPESSOAATIVA       ,RQAGENDACONF       ,INDCOMPLEMENTOSQL       ,INDPRODUTIVO       ,EXIGEDETALHE       ,CONCLUSIVO       ,FORCACONCLUSAO       ,RECEPTIVO       ,ATIVO       ,IDENTSITUACAO       ,EXIGEVENDEDOR       ,EXIGEMOTIVO       ,EXIGEPRODUTO       ,EXIGEDEPTO       ,EXIGECAMPANHA       ,EMUSOX       ,EXIGECLIENTEATIVO       ,EXIGEQTDE       ,EXIGEVALOR              )        AS  SELECT RES.RESULTADO       ,RES.ACAO       ,RES.DESCRICAO       ,RES.DESCREDUZIDA       ,RES.ORDEM       ,ISNULL(ACA.DESCRICAO, ' (rec)') ++ ' - ' ++ RES.DESCRICAO                    AS DESCRICAOFULL       ,ISNULL(ACA.DESCREDUZIDA, ' (rec)') ++ ' - ' ++ RES.DESCREDUZIDA              AS DESCREDFULL       ,ISNULL(ACA.DESCRICAO, ' (rec)')                                              AS ACAODESCRICAO       ,ISNULL(ACA.DESCREDUZIDA, ' (rec)')                                           AS DESCREDUZIDAACAO       ,RES.EMUSO       ,PRES.CODPROCESSO       ,CPRS.DESCRRED                                                             AS TIPOPROCESSO       ,RES.ADVERTENCIA       ,RES.ASSUNTOCMPL       ,RES.ASSUNTOEMAIL       ,RES.CANALPADRAO       ,RES.CMPLTTXTPADRAO       ,RES.DESCQTDE       ,RES.DESCVALOR       ,RES.PCTE       ,RES.QTDEMAXPORACAO             ,CTRLINTERATIVO       ,CTRLCONCLUSAO       ,CTRLDETALHE       ,CTRLFORMACONTATO       ,CTRLREAGENDA       ,CTRLCONFIRMAREAG       ,CTRLREAGENDASILO       ,CTRLMUDARATDREAG       ,CTRLFORMULARIO       ,CTRLDURACAO       ,CTRLVALOR       ,CTRLPRODUTIVO       ,CTRLPRODUTO       ,CTRLVENDEDOR       ,CTRLMOTIVO       ,CTRLDEPARTAMENTO       ,CTRLCAMPANHA       ,CTRLCONTATOPF       ,CTRLCONTATOPJ       ,CTRLCLIENTEATIVO       ,CTRLDETALHEPROC       ,CTRLDESCRSTATUSPROC       ,CTRLSTATUSPROC       ,CTRLPERSPECTIVAPROC       ,CTRLVALORPROC       ,CTRLDTAENCERRAPROC       ,CTRLPROJETO       ,CTRLIMAGEM       ,CTRLCTIDISPONIVEL       ,CTRLRESUMOPROC       ,CASE RES.CTRLCOMPLEMENTO     WHEN 1 THEN 1 WHEN 9 THEN 1 ELSE 0       END AS INDCOMPLEMENTO       ,CASE RES.CTRLCONCLUSAO       WHEN 1 THEN 1 ELSE 0                     END AS INDPERMCONCLUIR       ,CASE RES.CTRLCONCLUSAO       WHEN 1 THEN 0 WHEN 9 THEN 1 ELSE 0       END AS INDCONCLUI       ,CASE RES.CTRLINTERATIVO      WHEN 1 THEN 1 ELSE 0                     END AS INDINCLMANUAL       ,CASE RES.CTRLREAGENDA        WHEN 1 THEN 1 ELSE 0                     END AS INDPERMREAGENDAR       ,0                                                                         AS INDPERMEMAIL       ,CASE RES.CTRLCLIENTEATIVO    WHEN 1 THEN 1 WHEN 9 THEN 1 ELSE 0       END AS RQPESSOAATIVA       ,CASE RES.CTRLAGENDACONF      WHEN 1 THEN 1 WHEN 9 THEN 1 ELSE 0       END AS RQAGENDACONF       ,CASE RES.CTRLCMPLSQL         WHEN 1 THEN 1 ELSE 0                     END AS INDCOMPLEMENTOSQL        ,CASE RES.CTRLPRODUTIVO       WHEN 0 THEN 0 ELSE 1                     END AS INDPRODUTIVO             ,CASE RES.CTRLDETALHE         WHEN 0 THEN 'N' ELSE 'S'                 END AS EXIGEDETALHE       ,CASE RES.CTRLCONCLUSAO       WHEN 0 THEN 'N' ELSE 'S'                 END AS CONCLUSIVO       ,CASE RES.CTRLCONCLUSAO       WHEN 9 THEN 'S' ELSE 'N'                 END AS FORCACONCLUSAO       ,CASE RES.ACAO                WHEN NULL THEN 'S' ELSE 'N'              END AS RECEPTIVO       ,CASE RES.ACAO                WHEN NULL THEN 'N' ELSE 'S'              END AS ATIVO       ,CASE RES.CTRLPRODUTIVO       WHEN 0 THEN 'N' ELSE 'S'                 END AS IDENTSITUACAO       ,CASE RES.CTRLVENDEDOR        WHEN 0 THEN 'N' ELSE 'S'                 END AS EXIGEVENDEDOR       ,CASE RES.CTRLMOTIVO          WHEN 0 THEN 'N' ELSE 'S'                 END AS EXIGEMOTIVO       ,CASE RES.CTRLPRODUTO         WHEN 0 THEN 'N' ELSE 'S'                 END AS EXIGEPRODUTO       ,CASE RES.CTRLDEPARTAMENTO    WHEN 0 THEN 'N' ELSE 'S'                 END AS EXIGEDEPTO       ,CASE RES.CTRLCAMPANHA        WHEN 0 THEN 'N' ELSE 'S'                 END AS EXIGECAMPANHA       ,CASE RES.EMUSO               WHEN 0 THEN 'N' ELSE 'S'                 END AS EMUSOX       ,CASE RES.CTRLCLIENTEATIVO    WHEN 0 THEN 'N' ELSE 'S'                 END AS EXIGECLIENTEATIVO       ,CASE RES.CTRLQTDE            WHEN 9 THEN 'S' ELSE 'N'                 END AS EXIGEQTDE       ,CASE RES.CTRLVALOR           WHEN 9 THEN 'S' ELSE 'N'                 END AS EXIGEVALOR        FROM   IV_RESULTADO RES LEFT   JOIN IV_ACAO ACA ON ACA.ACAO = RES.ACAO LEFT   JOIN IV_PROCRESULTADO PRES JOIN   IV_CODPROCESSO CPRS ON CPRS.CODPROCESSO = PRES.CODPROCESSO ON  PRES.RESULTADO = RES.RESULTADO    